mod database;

// Generated by build.rs: every `#[command(group)]` fn, from any module or file,
// is collected into one handler. No lists to maintain.
mod groups {
  include!(concat!(env!("OUT_DIR"), "/groups.rs"));
}

fn on_startup(app: &mut tauri::App) -> Result<(), Box<dyn std::error::Error>> {
  database::init_db(app.handle())?;
  Ok(())
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
  tauri::Builder::default()
    .setup(|app| on_startup(app))
    .plugin(tauri_plugin_opener::init())
    .invoke_handler(groups::handler())
    .run(tauri::generate_context!())
    .expect("error while running tauri application");
}
